148	            &self.context(),
149	            &ProviderRequest {
150	                id,
151	                operation,
152	                artifacts,
153	            },
154	        )
155	    }
156	
157	    fn observe_within(
158	        &self,
159	        id: &ReleaseOperationId,
160	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
161	        patience: std::time::Duration,
162	    ) -> Result<ProviderObservationV1, GraphError> {
163	        let operation = self.prepared_operation(id)?;
164	        checked_provider_for(operation)?.observe(
165	            &self.context().with_patience(patience),
166	            &ProviderRequest {
167	                id,
168	                operation,
169	                artifacts,
170	            },
171	        )
172	    }
