174	    fn publish(
175	        &self,
176	        permit: &ApplyPermit,
177	        proof: &AbsentProof,
178	        id: &ReleaseOperationId,
179	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
180	    ) -> Result<ExactEvidence, GraphError> {
181	        let operation = self.prepared_operation(id)?;
182	        checked_provider_for(operation)?.publish(
183	            &self.context(),
184	            &ProviderRequest {
185	                id,
186	                operation,
187	                artifacts,
188	            },
189	            &EffectAuthorization { permit, proof },
190	        )
191	    }
