194	        let Ok(operation) = self.prepared_operation(id) else {
195	            return false;
196	        };
197	        checked_provider_for(operation).is_ok_and(|provider| {
198	            provider.defers_confirmation(&ProviderRequest {
199	                id,
200	                operation,
201	                artifacts: None,
202	            })
203	        })
204	    }
