206	    fn issue(
207	        &self,
208	        permit: &ApplyPermit,
209	        proof: &AbsentProof,
210	        id: &ReleaseOperationId,
211	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
212	    ) -> Result<(), GraphError> {
