270	/// Builds an intent whose declared binary slots are bound to the current
271	/// coordinator workflow. Callers recovering an old release source must pass
272	/// the current coordinator revision here, never substitute the source SHA.
273	///
274	/// Returns advisory diagnostics from derivation (e.g. an artifact owner selected
275	/// without its product) alongside the intent, for a caller to surface.
276	pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
277	    root: &Path,
278	    locator: &L,
279	    runner: &R,
280	    decision: &ReleaseDecisionV1,
281	    trust_profile: ExecutionTrustProfileV1,
282	    artifact_policy: ArtifactBuildPolicy,
283	) -> Result<(ReleaseIntentV1, Vec<callisto_model::Diagnostic>), GraphError> {
284	    let root = canonical_root(root)?;
285	    let workspace = Workspace::load(root.clone(), locator, runner)?;
286	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
287	    let mut diagnostics = Vec::new();
288	    let intent = derive_release_intent(
289	        &workspace,
290	        decision,
291	        source.clone(),
292	        trust_profile,
293	        Some(&artifact_policy),
294	        GitRemoteRequirement::Required,
295	        &mut diagnostics,
296	    )?;
297	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
298	        return Err(GraphError::ReleaseIntentStale {
299	            reason: StaleReason::source_identity_changed(),
300	        });
301	    }
