317	pub fn validate_local_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
318	    root: &Path,
319	    locator: &L,
320	    runner: &'a R,
321	    received: ReleaseIntentV1,
322	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
323	    validate_intent(root, locator, runner, received, ReleaseCheckout::AnyHead)
324	}
