216	) -> Result<(), GraphError> {
217	    let attestation_policy = &entry.slot.attestation_policy;
218	    let repository_slug = attestation_policy.repository.as_slug();
219	    let workflow = format!("{repository_slug}/{}", attestation_policy.workflow_path);
220	    let path_argument = path.to_string_lossy();
221	    let source_commit = entry.attestation.source_commit.as_str();
222	    let args = [
223	        "attestation",
224	        "verify",
225	        path_argument.as_ref(),
226	        "--repo",
227	        repository_slug.as_str(),
228	        "--signer-workflow",
229	        workflow.as_str(),
230	        "--signer-digest",
